"""Static site generator for ToolScout (AI tools directory) — minimal premium theme + tool landing pages."""
import os, re, json, datetime

ROOT = os.path.dirname(os.path.abspath(__file__))
CAT_DIR = os.path.join(ROOT, "categories")
TOOLS_DIR = os.path.join(ROOT, "tools")
ASSETS_DIR = os.path.join(ROOT, "assets")
ASSETS_IMG_DIR = os.path.join(ROOT, "assets", "images")
BLOG_DIR = os.path.join(ROOT, "blog")
REVIEWS_DIR = os.path.join(ROOT, "reviews")
for d in (ROOT, CAT_DIR, TOOLS_DIR, ASSETS_DIR, ASSETS_IMG_DIR, BLOG_DIR, REVIEWS_DIR):
    os.makedirs(d, exist_ok=True)

SITE_NAME = "ToolScout"
LOGO_TEXT = "ToolScout.in"
SITE_TAGLINE = "The quiet way to find the right AI tool"
SITE_DESC = "ToolScout is a directory that helps you discover, compare and choose the best AI tools for writing, images, video, coding, productivity, marketing, chatbots and audio."
SITE_URL = "https://www.toolscout.in"
