for _rev in REVIEWS:
    _rev["tool"] = TOOLS_BY_NAME[_rev["tool_name"]]
REVIEWS_BY_SLUG = {_rev["tool"]["slug"]: _rev for _rev in REVIEWS}

def rating_display(t):
    r = t.get("deep", {}).get("reviews")
    if not r:
        return None
    for src, label in (("g2", "G2"), ("capterra", "Capterra"), ("app_store", "App Store"), ("chrome_store", "Chrome Web Store")):
        val = r.get(f"{src}_rating")
        if val:
            count = r.get(f"{src}_count", "")
            return f"{label} {val}" + (f" ({count})" if count else "")
    return None

# ---------- structured data (JSON-LD) for SEO / AEO ----------

def _parse_rating(s):
    if not s:
        return None
    m = re.search(r"[\d.]+", s)
    return float(m.group()) if m else None

def _parse_count(s):
    if not s:
        return 0
    m = re.search(r"\d[\d,]*", s)
    return int(m.group().replace(",", "")) if m else 0

def _script(data):
    return f'<script type="application/ld+json">{json.dumps(data, ensure_ascii=False)}</script>'

def org_website_jsonld():
    org = {
        "@context": "https://schema.org", "@type": "Organization",
        "name": SITE_NAME, "url": f"{SITE_URL}/",
        "description": SITE_DESC,
    }
    website = {
        "@context": "https://schema.org", "@type": "WebSite",
        "name": SITE_NAME, "url": f"{SITE_URL}/",
        "description": SITE_DESC,
        "potentialAction": {
            "@type": "SearchAction",
            "target": {"@type": "EntryPoint", "urlTemplate": f"{SITE_URL}/all-tools.html?q={{search_term_string}}"},
            "query-input": "required name=search_term_string",
        },
    }
    return _script(org) + "\n" + _script(website)

def tool_jsonld(t, cat):
    d = t.get("deep")
    page_url = f"{SITE_URL}/tools/{t['slug']}.html"
    software = {
        "@context": "https://schema.org", "@type": "SoftwareApplication",
        "name": t["name"], "description": t["desc"], "url": t["url"],
        "applicationCategory": cat["name"], "operatingSystem": "Web",
    }
    if t.get("last_checked"):
        software["dateModified"] = t["last_checked"]
    graph_scripts = []
    if d:
        r = d.get("reviews") or {}
        g2, cap = _parse_rating(r.get("g2_rating")), _parse_rating(r.get("capterra_rating"))
        ratings = [x for x in (g2, cap) if x and x <= 5]
        if t['slug'] in PARTNER_SLUGS or t['slug'] in FOUNDER_SLUGS:
            ratings = []   # no self-serving rating markup for partner/founder listings
        if ratings:
            count = _parse_count(r.get("g2_count")) + _parse_count(r.get("capterra_count"))
            software["aggregateRating"] = {
                "@type": "AggregateRating",
                "ratingValue": round(sum(ratings) / len(ratings), 1),
                "bestRating": "5", "worstRating": "1",
                "ratingCount": max(count, 1),
            }
        if d.get("pricing_plans"):
            offers = []
            for p in d["pricing_plans"]:
                m = re.search(r"[\d][\d,.]*", p["price"])
                offers.append({
                    "@type": "Offer", "name": p["name"], "priceCurrency": "USD",
                    "price": m.group().replace(",", "") if m else "0",
                    "description": p.get("billing", ""),
                })
            software["offers"] = offers
    graph_scripts.append(_script(software))
    if d and d.get("faq"):
        faqpage = {
            "@context": "https://schema.org", "@type": "FAQPage",
            "mainEntity": [
                {"@type": "Question", "name": qa["q"],
                 "acceptedAnswer": {"@type": "Answer", "text": qa["a"]}}
                for qa in d["faq"]
            ],
        }
        graph_scripts.append(_script(faqpage))
    breadcrumb = {
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": f"{SITE_URL}/"},
            {"@type": "ListItem", "position": 2, "name": cat["name"], "item": f"{SITE_URL}/categories/{cat['slug']}.html"},
            {"@type": "ListItem", "position": 3, "name": t["name"], "item": page_url},
        ],
    }
    graph_scripts.append(_script(breadcrumb))
    return "\n".join(graph_scripts)

