def page(title, description, body, depth=0, extra_head="", url_path=""):
    prefix = "../" if depth else ""
    canonical = f"{SITE_URL}/{url_path}" if url_path else f"{SITE_URL}/"
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{title}</title>
<meta name="description" content="{description}">
<link rel="canonical" href="{canonical}">
<meta property="og:title" content="{title}">
<meta property="og:description" content="{description}">
<meta property="og:type" content="website">
<meta property="og:url" content="{canonical}">
<meta name="twitter:card" content="summary">
<meta name="twitter:title" content="{title}">
<meta name="twitter:description" content="{description}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@1,400;1,500&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="{prefix}assets/style.css">
{extra_head}
</head>
<body>
{nav(depth)}
<main>
{body}
</main>
{footer(depth)}
<script src="{prefix}assets/script.js"></script>
</body>
</html>"""

def tool_card(t, depth=0, index=0):
    prefix = "../" if depth else ""
    tags = "".join(f'<span class="tag">{tag}</span>' for tag in t["tags"])
    cat_link = f'{prefix}categories/{t["cat_slug"]}.html'
    tool_link = f'{prefix}tools/{t["slug"]}.html'
    d = stagger(index)
    return f"""
<article class="tool-card reveal tilt" data-category="{t['cat_slug']}" data-name="{t['name'].lower()}" style="transition-delay:{d}s">
  <div class="tool-card-top">
    <h3><a href="{tool_link}">{t['name']}</a>{partner_badge(t['slug'])}</h3>
    <a class="cat-label" href="{cat_link}">{t['category']}</a>
  </div>
  <p class="tool-tagline">{t['tagline']}</p>
  <p class="tool-desc">{t['desc']}</p>
  <p class="tool-pricing"><strong>Pricing</strong> {t['pricing']}</p>
  {('<p class="muted small">' + disclosure_text(t['slug']) + '</p>') if disclosure_text(t['slug']) else ''}
  <div class="tags">{tags}</div>
  <div class="card-actions">
    <a class="btn btn-primary magnetic" href="{tool_link}">More details <span class="arrow">&rarr;</span></a>
    <a class="text-link" href="{t['url']}" target="_blank" rel="noopener sponsored">Visit website <span class="arrow">&rarr;</span></a>
  </div>
</article>
"""

def category_card(cat, depth=0, index=0):
    prefix = "../" if depth else ""
    d = stagger(index)
    num = str(index + 1).zfill(2)
    return f"""
<a class="category-card reveal tilt" href="{prefix}categories/{cat['slug']}.html" style="transition-delay:{d}s">
  <div class="cat-num">{num}</div>
  <div class="cat-icon">{cat['icon']}</div>
  <h3>{cat['name']}</h3>
  <p class="muted">{cat['short']}</p>
  <span class="cat-count">{len(cat['tools'])} tools <span class="arrow">&rarr;</span></span>
</a>
"""

