# Two curated, well-known 3-tool comparisons per category, built entirely from data
# already researched for each tool's own page (desc, pricing, features, pros, cons,
# best_for, and reviews where verified) -- no new research required.

MULTI_COMPARISONS_SPEC = [
    ("writing-content", ["Jasper", "Copy.ai", "Writesonic"]),
    ("writing-content", ["Grammarly", "Wordtune", "Sapling"]),
    ("image-generation", ["Midjourney", "DALL-E 3", "Adobe Firefly"]),
    ("image-generation", ["BGEraser", "Pebblely", "PhotoPacks.AI"]),
    ("video-generation", ["Runway", "Kling AI", "Luma Dream Machine"]),
    ("video-generation", ["HeyGen", "Synthesia", "Vyond"]),
    ("coding-development", ["GitHub Copilot", "Cursor", "Claude Code"]),
    ("coding-development", ["Replit AI", "Windsurf", "Supermaven"]),
    ("productivity-automation", ["Notion AI", "ClickUp AI", "Motion"]),
    ("productivity-automation", ["Zapier", "Ishi", "Autonoma"]),
    ("marketing-seo", ["Surfer SEO", "Semrush", "Clearscope"]),
    ("marketing-seo", ["HubSpot AI Tools", "Simplified", "Frase"]),
    ("chatbots-assistants", ["ChatGPT", "Claude", "Google Gemini"]),
    ("chatbots-assistants", ["Perplexity", "Poe", "HARPA AI"]),
    ("audio-voice", ["ElevenLabs", "Murf AI", "WellSaid Labs"]),
    ("audio-voice", ["Descript", "Otter.ai", "Krisp"]),
    ("aeo-tools", ["Profound", "Scrunch AI", "AthenaHQ"]),
    ("aeo-tools", ["Adobe LLM Optimizer", "Conductor", "BrightEdge"]),
    ("customer-support", ["Gorgias", "LivePerson", "Ultimate"]),
    ("customer-support", ["Chatling", "DocsBot AI", "My AskAI"]),
    ("business-sales", ["Apollo.io", "Outreach", "Salesloft"]),
    ("business-sales", ["Gong", "Chorus.ai", "Clari"]),
    ("data-analysis", ["DataRobot", "H2O.ai", "Akkio"]),
    ("data-analysis", ["Julius AI", "Polymer", "Rows AI"]),
    ("design", ["Uizard", "Framer AI", "Galileo AI"]),
    ("design", ["Remove.bg", "Slazzer", "Cleanup.pictures"]),
    ("nocode-lowcode", ["Dify", "Stack AI", "BuildShip"]),
    ("nocode-lowcode", ["B12", "Durable", "Hocoos AI Website Builder"]),
    ("presentations", ["Napkin", "Plus AI", "Decktopus"]),
    ("presentations", ["Slidebean", "Prezent.ai", "Presentations.AI"]),
]

CATEGORIES_BY_SLUG = {c["slug"]: c for c in CATEGORIES}

def build_multi_comparison(cat_slug, names):
    cat = CATEGORIES_BY_SLUG[cat_slug]
    tools = [TOOLS_BY_NAME[n] for n in names]
    slug = "-vs-".join(slugify(n) for n in names)
    title = f"{names[0]} vs {names[1]} vs {names[2]}: Which {cat['name']} Tool Should You Choose in 2026?"
    meta_description = f"A side-by-side comparison of {names[0]}, {names[1]} and {names[2]} — pricing, features, pros, cons and who each {cat['name'].lower()} tool is really built for."
    dek = f"{names[0]}, {names[1]} and {names[2]} all solve {cat['name'].lower()} problems, but in different ways. Here's how their pricing, features and ideal users actually compare."
    return {"slug": slug, "cat": cat, "tools": tools, "title": title, "meta_description": meta_description, "dek": dek, "faq": None}

_removed_names = {_t["name"] for _t in REMOVED_TOOLS}
MULTI_COMPARISONS_SPEC = [(cs, names) for cs, names in MULTI_COMPARISONS_SPEC if not (set(names) & _removed_names)]
MULTI_COMPARISONS = [build_multi_comparison(cs, names) for cs, names in MULTI_COMPARISONS_SPEC]

def _feature_count(t):
    return len(t.get("features") or [])

def multi_compare_jsonld(comp):
    page_url = f"{SITE_URL}/blog/{comp['slug']}.html"
    article = {
        "@context": "https://schema.org", "@type": "Article",
        "headline": comp["title"], "description": comp["meta_description"],
        "url": page_url, "datePublished": "2026-08-21", "dateModified": "2026-08-21",
        "author": {"@type": "Organization", "name": SITE_NAME, "url": f"{SITE_URL}/"},
        "publisher": {"@type": "Organization", "name": SITE_NAME},
    }
    graph_scripts = [_script(article)]
    breadcrumb = {
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": f"{SITE_URL}/"},
            {"@type": "ListItem", "position": 2, "name": "Blog", "item": f"{SITE_URL}/blog/index.html"},
            {"@type": "ListItem", "position": 3, "name": comp["title"], "item": page_url},
        ],
    }
    graph_scripts.append(_script(breadcrumb))
    return "\n".join(graph_scripts)

def multi_compare_body(comp, depth=1):
    prefix = "../" if depth else ""
    tools = comp["tools"]
    names = [t["name"] for t in tools]
    cat = comp["cat"]

    header_cells = "".join(f"<th>{n}</th>" for n in names)

    def row(label, getter):
        cells = "".join(f"<td>{getter(t) or '&mdash;'}</td>" for t in tools)
        return f"<tr><td>{label}</td>{cells}</tr>"

    def list_row(label, key):
        cells = ""
        for t in tools:
            items = t.get(key) or []
            cells += "<td>" + ("<ul class=\"compare-list\">" + "".join(f"<li>{i}</li>" for i in items[:4]) + "</ul>" if items else "&mdash;") + "</td>"
        return f"<tr><td>{label}</td>{cells}</tr>"

    table_html = f"""<div class="table-wrap reveal"><table class="compare-table">
      <thead><tr><th>Tool</th>{header_cells}</tr></thead>
      <tbody>
      {row("Tagline", lambda t: t.get("tagline"))}
      {row("Pricing", lambda t: t.get("pricing"))}
      {row("Rating", lambda t: rating_display(t))}
      {list_row("Key features", "features")}
      {list_row("Pros", "pros")}
      {list_row("Cons", "cons")}
      {row("Best for", lambda t: t.get("best_for"))}
      </tbody>
    </table></div>"""

    profile_sections = ""
    for t in tools:
        tool_link = f'{prefix}tools/{t["slug"]}.html'
        pros_html = "".join(f'<li class="reveal"><span class="check">&#10003;</span>{p}</li>' for p in (t.get("pros") or [])[:3])
        cons_html = "".join(f'<li class="reveal">{c}</li>' for c in (t.get("cons") or [])[:3])
        profile_sections += f"""
<section class="container section narrow" style="padding-top:0;">
  <h2 class="reveal">About {t['name']}</h2>
  <p class="reveal">{t.get('desc', '')}</p>
  <p class="muted reveal"><strong>Pricing:</strong> {t.get('pricing', '')}</p>
  <ul class="feature-list">{pros_html}</ul>
  <p class="reveal"><a class="text-link" href="{tool_link}">Read the full {t['name']} review <span class="arrow">&rarr;</span></a></p>
</section>"""

    feat_idx = max(range(len(tools)), key=lambda i: _feature_count(tools[i]))
    verdict_items = "".join(
        f'<li class="reveal"><span class="check">&#10003;</span><strong>{t["name"]}</strong> — {t.get("best_for", "")}</li>'
        for t in tools
    )

    pricing_sentence = "; ".join(f"{t['name']} ({t.get('pricing', 'pricing not listed')})" for t in tools)
    rated = [t for t in tools if rating_display(t)]
    if rated:
        rating_answer = " ".join(f"{t['name']} shows {rating_display(t)}." for t in rated) + " Weigh this alongside the feature and pricing comparison above, not as the only factor."
    else:
        rating_answer = f"None of {names[0]}, {names[1]} or {names[2]} has a review count we could independently verify on G2, Capterra or Trustpilot as of writing, so lean on the feature and pricing comparison above along with your own trial."

    faq = [
        {"q": f"Which is cheaper: {names[0]}, {names[1]} or {names[2]}?", "a": f"Based on published pricing: {pricing_sentence}. Exact value depends on your usage volume and which features you actually need, so check each tool's full pricing breakdown before deciding."},
        {"q": f"Which of these three has the best reviews?", "a": rating_answer},
        {"q": f"Which has the most features: {names[0]}, {names[1]} or {names[2]}?", "a": f"Of the three, {tools[feat_idx]['name']} lists the most features in our comparison above, though more features doesn't automatically mean it's the better fit — a simpler, more focused tool can win for a specific use case."},
        {"q": f"Can I use more than one of these {cat['name'].lower()} tools together?", "a": f"Yes — many teams run more than one {cat['name'].lower()} tool for different parts of their workflow rather than picking a single winner. Start with whichever one matches your primary use case, and add a second only if you hit a real gap."},
    ]
    comp["faq"] = faq
    faq_html = "".join(
        f'<div class="faq-item reveal" style="transition-delay:{stagger(i,6,0.05)}s"><h4>{qa["q"]}</h4><p class="muted">{qa["a"]}</p></div>'
        for i, qa in enumerate(faq)
    )

    other_in_cat = [c for c in MULTI_COMPARISONS if c["cat"]["slug"] == cat["slug"] and c["slug"] != comp["slug"]]
    other_html = "".join(
        f'<a class="alt-card reveal tilt" href="{prefix}blog/{c["slug"]}.html" style="transition-delay:{stagger(i)}s">'
        f'<h4>{" vs ".join(t["name"] for t in c["tools"])}</h4><p class="muted">{c["dek"]}</p><span class="text-link">Read comparison <span class="arrow">&rarr;</span></span></a>'
        for i, c in enumerate(other_in_cat)
    )
    compare_tool_url = f'{prefix}compare.html?category={cat["slug"]}&tools=' + ",".join(t["slug"] for t in tools)

    return f"""
<section class="container section narrow page-hero">
  <div class="breadcrumb reveal">
    <a href="{prefix}index.html">Home</a> <span>/</span>
    <a href="{prefix}blog/index.html">Blog</a> <span>/</span>
    <span>{names[0]} vs {names[1]} vs {names[2]}</span>
  </div>
  <div class="kicker reveal">Comparison</div>
  <h1 class="reveal" style="transition-delay:.08s">{comp['title']}</h1>
  <p class="hero-sub-left reveal" style="transition-delay:.16s">{comp['dek']}</p>
</section>

<section class="container section" style="padding-top:0;">
  <h2 class="reveal">{names[0]} vs {names[1]} vs {names[2]} at a glance</h2>
  {table_html}
</section>

{profile_sections}

<section class="container section narrow" style="padding-top:0;">
  <h2 class="reveal">Quick picks</h2>
  <ul class="feature-list">{verdict_items}</ul>
</section>

<section class="container section narrow" style="padding-top:0;">
  <h2 class="reveal">Frequently asked questions</h2>
  <div class="faq-list">{faq_html}</div>
</section>

{f'''<section class="container section" style="padding-top:0;">
  <h2 class="reveal">More {cat["name"]} comparisons</h2>
  <div class="alt-grid">{other_html}</div>
</section>''' if other_html else ''}

<section class="container section cta-band reveal">
  <h2>Want to compare different tools?</h2>
  <p class="muted">Use our interactive Compare tool to pick any {cat['name'].lower()} tools yourself, or browse the full category.</p>
  <a href="{compare_tool_url}" class="btn btn-primary magnetic">Open this comparison in Compare tool <span class="arrow">&rarr;</span></a>
  <p class="muted small" style="margin-top:16px;"><a href="{prefix}categories/{cat['slug']}.html">See all {cat['name']} tools</a> on {SITE_NAME}.</p>
</section>
"""

for comp in MULTI_COMPARISONS:
    body = multi_compare_body(comp, depth=1)
    with open(os.path.join(BLOG_DIR, f"{comp['slug']}.html"), "w") as f:
        f.write(page(comp["title"], comp["meta_description"], body, depth=1, extra_head=multi_compare_jsonld(comp), url_path=f"blog/{comp['slug']}.html"))

