# ---------- assets: css ----------

css = """
:root {
  --bg: #FBFBFA;
  --surface: #FFFFFF;
  --ink: #14141A;
  --muted: #767680;
  --muted-2: #55555F;
  --line: #ECECE8;
  --line-2: #E3E1D8;
  --tint: #F3F1EA;
  --gold: #B08D57;
  --gold-dark: #8C6D3F;
  --green: #2F6B4F;
  --red: #A23B3B;
  --ease: cubic-bezier(.16,1,.3,1);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.6;
}
.container { max-width: 1120px; margin: 0 auto; padding: 0 24px; }
.section { padding: 64px 24px; }
.section.narrow { max-width: 720px; margin: 0 auto; }
.page-hero { padding-bottom: 40px; }
h1 { font-size: 2.6rem; font-weight: 600; letter-spacing: -1px; margin: 0 0 14px; line-height: 1.15; }
h1 em { font-family: 'Fraunces', serif; font-style: italic; font-weight: 400; color: var(--muted-2); }
h2 { font-size: 1.5rem; font-weight: 600; letter-spacing: -0.4px; margin: 40px 0 20px; }
h2:first-child { margin-top: 0; }
h3 { margin: 0 0 6px; font-weight: 600; }
h4 { margin: 0 0 12px; font-weight: 600; font-size: 0.95rem; }
a { color: var(--ink); text-decoration: none; }
p { margin: 0 0 16px; }
.muted { color: var(--muted); }
.small { font-size: 0.85rem; }
.lede { font-size: 1.1rem; color: var(--muted-2); }

/* cursor */
.cursor-ring { position: fixed; top: 0; left: 0; width: 26px; height: 26px; border: 1px solid var(--gold); border-radius: 50%; pointer-events: none; z-index: 999; transform: translate(-50%,-50%); transition: width .25s var(--ease), height .25s var(--ease), background .25s var(--ease), border-color .25s var(--ease); }
.cursor-ring.hover { width: 52px; height: 52px; background: rgba(176,141,87,0.1); }
@media (pointer: coarse) { .cursor-ring { display: none; } }

/* header */
.site-header { position: sticky; top: 0; background: rgba(251,251,250,0.85); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); z-index: 50; transition: padding .3s var(--ease), box-shadow .3s var(--ease); }
.site-header.scrolled { box-shadow: 0 1px 0 rgba(0,0,0,0.04); }
.nav-wrap { display: flex; align-items: center; justify-content: space-between; height: 68px; transition: height .3s var(--ease); }
.site-header.scrolled .nav-wrap { height: 56px; }
.logo { font-weight: 700; font-size: 1.15rem; letter-spacing: -0.3px; color: var(--ink); }
.logo .dot { color: var(--gold); }
.main-nav { display: flex; gap: 32px; }
.main-nav a { color: var(--muted-2); font-weight: 500; font-size: 0.92rem; position: relative; }
.main-nav a::after { content:''; position: absolute; left: 0; bottom: -4px; width: 0; height: 1px; background: var(--ink); transition: width .3s var(--ease); }
.main-nav a:hover { color: var(--ink); }
.main-nav a:hover::after { width: 100%; }
.nav-toggle { display: none; background: none; border: none; font-size: 1.4rem; cursor: pointer; color: var(--ink); }

/* reveal-on-scroll */
.reveal { opacity: 0; transform: translateY(28px); transition: opacity .8s var(--ease), transform .8s var(--ease); will-change: opacity, transform; }
.reveal.in-view { opacity: 1; transform: translateY(0); }

/* hero */
.hero { position: relative; padding: 96px 24px 56px; text-align: center; overflow: hidden; }
.hero-canvas { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 0; }
.hero .container { position: relative; z-index: 1; }
.kicker { display: inline-block; font-size: 0.76rem; letter-spacing: 2px; text-transform: uppercase; color: var(--gold-dark); font-weight: 700; margin-bottom: 20px; }
.hero-sub { color: var(--muted); max-width: 540px; margin: 0 auto 36px; font-size: 1.08rem; }
.search-wrap { max-width: 500px; margin: 0 auto; display: flex; align-items: center; gap: 0; border-bottom: 1px solid var(--ink); padding-bottom: 10px; }
.search-wrap input { flex: 1; background: transparent; border: none; outline: none; padding: 8px 4px; font-size: 1rem; font-family: inherit; color: var(--ink); }
.search-wrap button { background: transparent; border: none; color: var(--ink); font-weight: 600; font-size: 0.95rem; cursor: pointer; display: flex; align-items: center; gap: 6px; font-family: inherit; }
.arrow { display: inline-block; transition: transform .3s var(--ease); }
a:hover .arrow, button:hover .arrow { transform: translateX(4px); }

/* marquee */
.marquee { overflow: hidden; white-space: nowrap; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 16px 0; background: var(--surface); }
.marquee-track { display: inline-block; font-size: 0.85rem; color: var(--muted); letter-spacing: 0.5px; animation: marquee 38s linear infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* stats */
.stats { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; text-align: center; padding-top: 56px; padding-bottom: 40px; }
.stat-num { font-family: 'Fraunces', serif; font-size: 2.6rem; font-weight: 500; color: var(--ink); }
.stat-label { color: var(--muted); font-size: 0.88rem; margin-top: 4px; }

/* tool of the day */
.totd-section { padding-top: 24px; }
.totd-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.totd-head .kicker { margin: 0; }
.totd-card { display: flex; flex-wrap: wrap; gap: 28px; justify-content: space-between; align-items: flex-start; background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 36px 40px; position: relative; overflow: hidden; }
.totd-card::before { content: ''; position: absolute; top: 0; left: 0; width: 4px; height: 100%; background: var(--gold); }
.totd-body { flex: 1 1 420px; }
.totd-body h2 { margin: 0 0 8px; font-size: 1.7rem; }
.totd-body h2 a { color: inherit; }
.totd-body .tool-tagline { font-weight: 600; color: var(--muted-2); margin: 0 0 10px; }
.totd-body .tool-desc { margin: 0 0 14px; }
.totd-actions { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; padding-top: 6px; }

/* why-us feature grid */
.feature-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; }
.feature-card { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 26px 24px; transition: transform .3s var(--ease), border-color .3s var(--ease); }
.feature-card:hover { border-color: var(--gold); transform: translateY(-4px); }
.feature-icon { font-size: 1.6rem; margin-bottom: 10px; }
.feature-card h3 { font-size: 1.02rem; margin: 0 0 8px; }
.feature-card p { margin: 0; font-size: 0.88rem; }
.feature-card a { color: var(--gold-dark); font-weight: 600; }

/* AI insights */
.insights-section { padding-top: 8px; }
.insights-head { display: flex; align-items: baseline; justify-content: space-between; flex-wrap: wrap; gap: 8px; margin-bottom: 20px; }
.insights-head h2 { margin: 0; }
.insights-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 18px; }
.insight-card { display: block; background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 24px 26px; transition: transform .3s var(--ease), border-color .3s var(--ease); }
.insight-card:hover { border-color: var(--gold); transform: translateY(-4px); }
.insight-num { font-family: 'Fraunces', serif; font-style: italic; font-size: 0.85rem; color: var(--gold-dark); display: block; margin-bottom: 10px; }
.insight-card h3 { font-size: 0.98rem; line-height: 1.4; margin: 0 0 8px; color: var(--ink); }
.insight-card p { font-size: 0.85rem; margin: 0 0 14px; }
.insight-source { font-size: 0.78rem; font-weight: 600; color: var(--muted-2); display: inline-flex; align-items: center; gap: 4px; }

/* buttons */
.btn { display: inline-flex; align-items: center; gap: 6px; padding: 13px 26px; border-radius: 999px; font-weight: 600; cursor: pointer; border: none; font-size: 0.92rem; font-family: inherit; transition: transform .25s var(--ease), background .25s var(--ease), color .25s var(--ease), border-color .25s var(--ease); }
.btn-primary { background: var(--ink); color: #fff; }
.btn-primary:hover { background: var(--gold-dark); }
.btn-outline { background: transparent; color: var(--ink); border: 1px solid var(--ink); }
.btn-outline:hover { background: var(--ink); color: #fff; }
.center-cta { text-align: center; margin-top: 36px; }
.magnetic { will-change: transform; }
.text-link { font-size: 0.85rem; font-weight: 600; color: var(--muted-2); display: inline-flex; align-items: center; gap: 4px; }
.text-link:hover { color: var(--ink); }

/* category grid */
.category-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 1px; background: var(--line); border: 1px solid var(--line); }
.category-card { background: var(--surface); padding: 30px 26px; display: block; position: relative; transition: background .3s var(--ease); }
.category-card:hover { background: var(--tint); }
.category-card::before { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 2px; background: var(--gold); transform: scaleX(0); transform-origin: left; transition: transform .4s var(--ease); }
.category-card:hover::before { transform: scaleX(1); }
.cat-num { font-family: 'Fraunces', serif; font-style: italic; font-size: 0.85rem; color: var(--gold-dark); margin-bottom: 14px; }
.cat-icon { font-size: 1.8rem; margin-bottom: 10px; }
.cat-icon.large { font-size: 3rem; }
.cat-icon.float { animation: bob 4.5s ease-in-out infinite; display: inline-block; }
@keyframes bob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.cat-count { color: var(--ink); font-weight: 600; font-size: 0.85rem; display: inline-flex; align-items: center; gap: 4px; margin-top: 6px; }

/* tool grid */
.tool-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
.tool-card { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 26px; display: flex; flex-direction: column; position: relative; overflow: hidden; transition: transform .35s var(--ease), box-shadow .35s var(--ease), border-color .35s var(--ease); transform-style: preserve-3d; }
.tool-card::before { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 2px; background: var(--gold); transform: scaleX(0); transform-origin: left; transition: transform .4s var(--ease); }
.tool-card:hover { border-color: var(--line-2); box-shadow: 0 24px 48px rgba(20,20,26,0.08); }
.tool-card:hover::before { transform: scaleX(1); }
.tool-card-top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.tool-card-top h3 { margin: 0; }
.tool-card-top h3 a { transition: color .25s var(--ease); }
.tool-card-top h3 a:hover { color: var(--gold-dark); }
.cat-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: var(--gold-dark); font-weight: 700; white-space: nowrap; }
.tool-tagline { font-weight: 600; margin: 8px 0 6px; font-size: 0.95rem; }
.tool-desc { color: var(--muted); font-size: 0.92rem; flex-grow: 1; }
.tool-pricing { font-size: 0.85rem; margin: 12px 0; color: var(--muted-2); }
.tool-pricing strong { color: var(--ink); font-weight: 600; margin-right: 4px; }
.tags { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 18px; }
.tag { background: var(--tint); color: var(--muted-2); font-size: 0.72rem; padding: 3px 10px; border-radius: 999px; }
.card-actions { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: auto; }

/* cat hero */
.cat-hero { display: flex; align-items: center; gap: 24px; }

/* tool detail page */
.breadcrumb { font-size: 0.82rem; color: var(--muted); margin-bottom: 28px; }
.breadcrumb a { color: var(--muted); }
.breadcrumb a:hover { color: var(--ink); }
.breadcrumb span { margin: 0 6px; }
.tool-hero-top { display: flex; align-items: flex-end; justify-content: space-between; gap: 32px; flex-wrap: wrap; }
.hero-sub-left { color: var(--muted); font-size: 1.05rem; max-width: 460px; margin: 0; }
.tool-hero-cta { text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 12px; }
.price-tag { font-size: 0.85rem; color: var(--muted-2); background: var(--tint); padding: 8px 16px; border-radius: 999px; }
.callout { border-left: 2px solid var(--gold); padding: 4px 0 4px 20px; margin: 8px 0 32px; }
.callout-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1.5px; color: var(--gold-dark); font-weight: 700; margin-bottom: 6px; }
.callout p { margin: 0; color: var(--muted-2); }
.feature-list { list-style: none; padding: 0; margin: 0 0 8px; display: grid; gap: 14px; }
.feature-list li { display: flex; align-items: flex-start; gap: 12px; font-size: 0.98rem; color: var(--muted-2); }
.feature-list .check { color: var(--gold-dark); font-weight: 700; margin-top: 2px; }
.pros-cons { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.pc-col { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 22px 24px; }
.pc-col h4 { text-transform: uppercase; letter-spacing: 1px; font-size: 0.78rem; }
.pc-pros h4 { color: var(--green); }
.pc-cons h4 { color: var(--red); }
.pc-col ul { margin: 0; padding-left: 18px; color: var(--muted-2); font-size: 0.92rem; }
.pc-col li { margin-bottom: 10px; }
.alt-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 16px; }
.alt-card { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 20px 22px; display: block; transition: transform .3s var(--ease), border-color .3s var(--ease); }
.alt-card:hover { border-color: var(--gold); transform: translateY(-4px); }
.alt-card p { font-size: 0.85rem; margin: 4px 0 12px; }

/* quick facts */
.quick-facts { list-style: none; margin: 0 0 8px; padding: 20px 24px; background: var(--tint); border-radius: 4px; display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 16px 24px; }
.qf-item dt { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 1px; color: var(--gold-dark); font-weight: 700; margin-bottom: 4px; }
.qf-item dd { margin: 0; font-size: 0.88rem; color: var(--ink); font-weight: 500; }
.qf-item dd a { color: var(--ink); border-bottom: 1px solid var(--line-2); }
.qf-item dd a:hover { border-color: var(--ink); }

/* rating chips */
.rating-row { display: flex; gap: 10px; margin-top: 14px; flex-wrap: wrap; }
.rating-chip { font-size: 0.85rem; background: var(--tint); padding: 6px 14px; border-radius: 999px; color: var(--muted-2); }
.rating-chip strong { color: var(--ink); }

/* detailed feature rows */
.feat-list { display: grid; gap: 22px; max-width: 760px; }
.feat-row { display: flex; gap: 18px; align-items: flex-start; }
.feat-num { font-family: 'Fraunces', serif; font-style: italic; color: var(--gold-dark); font-size: 1rem; min-width: 28px; }
.feat-row h4 { margin-bottom: 4px; font-size: 1rem; }
.feat-row p { margin: 0; font-size: 0.92rem; }

/* pricing plan cards */
.plan-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 20px; }
.plan-card { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 26px; }
.plan-card h4 { font-size: 1.05rem; margin-bottom: 8px; }
.plan-price { font-family: 'Fraunces', serif; font-size: 1.6rem; margin-bottom: 4px; }
.plan-billing { font-size: 0.8rem; margin-bottom: 16px; }
.plan-card ul { margin: 0; padding-left: 18px; font-size: 0.88rem; color: var(--muted-2); }
.plan-card li { margin-bottom: 8px; }

/* review sentiment */
.pc-neutral { color: var(--ink) !important; }

/* faq */
.faq-list { display: flex; flex-direction: column; gap: 22px; }
.faq-item h4 { font-size: 0.98rem; margin-bottom: 6px; }
.faq-item p { margin: 0; font-size: 0.92rem; }

/* all tools toolbar */
.toolbar { margin: 28px 0 0; display: flex; flex-direction: column; gap: 18px; }
#toolSearch { padding: 12px 4px; border: none; border-bottom: 1px solid var(--ink); background: transparent; font-size: 1rem; max-width: 360px; font-family: inherit; outline: none; }
.filter-bar { display: flex; flex-wrap: wrap; gap: 8px; }
.filter-btn { background: var(--surface); border: 1px solid var(--line); padding: 8px 16px; border-radius: 999px; cursor: pointer; font-size: 0.82rem; font-family: inherit; color: var(--muted-2); transition: all .25s var(--ease); }
.filter-btn:hover { border-color: var(--ink); color: var(--ink); }
.filter-btn.active { background: var(--ink); color: #fff; border-color: var(--ink); }

/* cta band */
.cta-band { text-align: center; background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 64px 24px; }
.cta-band p { margin: 10px 0 26px; }

/* submit form */
.submit-form { display: flex; flex-direction: column; gap: 18px; margin-top: 28px; }
.submit-form label { display: flex; flex-direction: column; gap: 8px; font-weight: 600; font-size: 0.88rem; color: var(--muted-2); }
.submit-form input, .submit-form select, .submit-form textarea { padding: 12px 4px; border-radius: 0; border: none; border-bottom: 1px solid var(--line); font-size: 0.95rem; font-family: inherit; background: transparent; color: var(--ink); transition: border-color .25s var(--ease); outline: none; }
.submit-form input:focus, .submit-form select:focus, .submit-form textarea:focus { border-color: var(--gold); }
.submit-form textarea { min-height: 90px; resize: vertical; }

/* verdict box + comparison table (blog) */
.verdict-box { background: var(--tint); border: 1px solid var(--line); border-radius: 4px; padding: 26px 28px; }
.verdict-box p { margin: 0; color: var(--muted-2); font-size: 0.98rem; }
.winner-tag { display: inline-block; background: var(--ink); color: #fff; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; padding: 5px 14px; border-radius: 999px; margin-bottom: 12px; font-weight: 700; }
.table-wrap { overflow-x: auto; }
.compare-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; min-width: 520px; }
.compare-table th, .compare-table td { padding: 14px 16px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }
.compare-table th { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 1px; color: var(--muted-2); font-weight: 700; }
.compare-table td.pl-col { font-weight: 600; color: var(--ink); background: var(--tint); }
.compare-table tr:last-child td { border-bottom: none; }
.compare-list { margin: 0; padding-left: 18px; font-size: 0.88rem; }
.compare-list li { margin-bottom: 4px; }
.hl-badge { display: inline-block; background: var(--tint); color: var(--gold-dark); font-size: 0.65rem; text-transform: uppercase; letter-spacing: 0.5px; padding: 2px 8px; border-radius: 999px; margin-left: 6px; font-weight: 700; vertical-align: middle; }

/* interactive compare tool */
.compare-picker { display: flex; flex-direction: column; gap: 24px; margin-bottom: 28px; }
.compare-field { display: flex; flex-direction: column; gap: 10px; }
.compare-field > span { font-size: 0.85rem; font-weight: 600; color: var(--ink); }
.compare-field select { max-width: 360px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 4px; font-family: inherit; font-size: 0.95rem; background: var(--bg); color: var(--ink); }
.compare-tools-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 10px; }
.compare-chip { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 4px; padding: 12px 14px; cursor: pointer; transition: border-color .2s var(--ease), background .2s var(--ease); font-size: 0.9rem; }
.compare-chip:hover { border-color: var(--gold); }
.compare-chip input[type="checkbox"] { accent-color: var(--ink); width: 16px; height: 16px; flex-shrink: 0; }
.compare-chip input[type="checkbox"]:disabled { opacity: 0.4; }
.compare-empty { padding: 32px 0; text-align: center; }
.compare-results { margin-top: 12px; }
.compare-hint { margin-top: 14px; }

/* footer */
.site-footer { background: var(--ink); color: #C9C9CE; margin-top: 40px; padding-top: 56px; }
.site-footer .logo { color: #fff; }
.site-footer h4 { color: #fff; margin: 0 0 14px; font-size: 0.9rem; font-weight: 600; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 32px; padding-bottom: 36px; }
.footer-links { display: flex; flex-direction: column; gap: 10px; }
.footer-links a { color: #C9C9CE; font-size: 0.9rem; transition: color .25s var(--ease); }
.footer-links a:hover { color: #fff; }
.disclosure { border-top: 1px solid #2A2A32; padding: 22px 24px 36px; }
.disclosure p { margin: 4px 0; font-size: 0.8rem; }

/* reviews */
.review-hero-shot { margin: 0 0 8px; background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 8px; }
.review-hero-shot img { display: block; width: 100%; height: auto; border-radius: 2px; }
.review-hero-shot figcaption { padding: 12px 6px 4px; font-size: 0.8rem; }
.review-hero-shot figcaption a { color: var(--gold-dark); font-weight: 600; }
.review-verdict { display: flex; gap: 24px; align-items: flex-start; }
.review-score-badge { flex-shrink: 0; display: flex; align-items: baseline; gap: 2px; background: var(--ink); color: #fff; border-radius: 4px; padding: 14px 16px; font-family: 'Fraunces', serif; }
.review-score-num { font-size: 2rem; font-weight: 500; line-height: 1; }
.review-score-badge .muted { color: #C9C9CE; font-size: 0.9rem; }
.rating-table .rt-score { font-weight: 700; color: var(--ink); white-space: nowrap; }
.review-banner { display: flex; align-items: center; gap: 18px; background: var(--tint); border: 1px solid var(--line); border-radius: 4px; padding: 18px 22px; transition: border-color .25s var(--ease), transform .25s var(--ease); }
.review-banner:hover { border-color: var(--gold); transform: translateY(-2px); }
.review-banner-score { flex-shrink: 0; font-family: 'Fraunces', serif; font-size: 1.4rem; color: var(--gold-dark); font-weight: 500; }
.review-banner-score .muted { font-size: 0.85rem; }
.review-banner-text { flex: 1; font-size: 0.92rem; color: var(--muted-2); }
.review-banner-text strong { color: var(--ink); display: block; margin-bottom: 2px; }

@media (max-width: 720px) {
  .review-verdict { flex-direction: column; }
  .review-banner { flex-wrap: wrap; }
  .main-nav { position: absolute; top: 68px; left: 0; right: 0; background: var(--surface); flex-direction: column; padding: 18px 24px; border-bottom: 1px solid var(--line); display: none; gap: 16px; }
  .main-nav.open { display: flex; }
  .nav-toggle { display: block; }
  .footer-grid { grid-template-columns: 1fr; }
  .stats { grid-template-columns: 1fr; }
  h1 { font-size: 2rem; }
  .cat-hero { flex-direction: column; align-items: flex-start; }
  .tool-hero-top { flex-direction: column; align-items: flex-start; }
  .tool-hero-cta { align-items: flex-start; text-align: left; }
  .pros-cons { grid-template-columns: 1fr; }
}
"""

