# ---------- sitemap.xml ----------

def _sitemap_url(loc, priority="0.7", changefreq="weekly"):
    return f"""  <url>
    <loc>{loc}</loc>
    <changefreq>{changefreq}</changefreq>
    <priority>{priority}</priority>
  </url>"""

_sitemap_entries = [
    _sitemap_url(f"{SITE_URL}/", "1.0", "weekly"),
    _sitemap_url(f"{SITE_URL}/all-tools.html", "0.9", "weekly"),
    _sitemap_url(f"{SITE_URL}/blog/", "0.7", "weekly"),
    _sitemap_url(f"{SITE_URL}/reviews/", "0.8", "weekly"),
    _sitemap_url(f"{SITE_URL}/about.html", "0.5", "monthly"),
    _sitemap_url(f"{SITE_URL}/submit-tool.html", "0.5", "monthly"),
    _sitemap_url(f"{SITE_URL}/compare.html", "0.7", "monthly"),
]
for cat in CATEGORIES:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/categories/{cat['slug']}.html", "0.8", "weekly"))
for t in ALL_TOOLS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/tools/{t['slug']}.html", "0.9", "weekly"))
for post in BLOG_POSTS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/blog/{post['slug']}.html", "0.7", "monthly"))
for comp in MULTI_COMPARISONS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/blog/{comp['slug']}.html", "0.7", "monthly"))
for rev in REVIEWS:
    _sitemap_entries.append(_sitemap_url(f"{SITE_URL}/reviews/{rev['slug']}.html", "0.9", "monthly"))

sitemap_xml = f"""<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
{chr(10).join(_sitemap_entries)}
</urlset>
"""
with open(os.path.join(ROOT, "sitemap.xml"), "w") as f:
    f.write(sitemap_xml)

# ---------- llms.txt (emerging LLM-crawler convention) ----------

_llms_lines = [
    f"# {SITE_NAME}", "",
    f"> {SITE_DESC}", "",
    "ToolScout is an independently researched directory of AI tools, organized by category, with "
    "comprehensive reviews covering pricing, features, pros and cons, and real user sentiment sourced from "
    "G2, Capterra and Reddit. Every tool page includes a quick-facts summary, detailed feature breakdown, "
    "full pricing tiers, and an FAQ section.", "",
    "## Categories", "",
]
for cat in CATEGORIES:
    _llms_lines.append(f"- [{cat['name']}]({SITE_URL}/categories/{cat['slug']}.html): {cat['short']}")
_llms_lines += ["", "## Tools", ""]
for cat in CATEGORIES:
    _llms_lines.append(f"### {cat['name']}")
    for t in cat["tools"]:
        _llms_lines.append(f"- [{t['name']}]({SITE_URL}/tools/{t['slug']}.html): {t['tagline']} — {t['pricing']}")
    _llms_lines.append("")
_llms_lines += ["## Reviews", ""]
for rev in REVIEWS:
    _llms_lines.append(f"- [{rev['headline']}]({SITE_URL}/reviews/{rev['slug']}.html): {rev['meta_description']}")
_llms_lines += ["", "## Blog", ""]
for comp in MULTI_COMPARISONS:
    _llms_lines.append(f"- [{comp['title']}]({SITE_URL}/blog/{comp['slug']}.html): {comp['dek']}")
for post in BLOG_POSTS:
    _llms_lines.append(f"- [{post['title']}]({SITE_URL}/blog/{post['slug']}.html): {post['dek']}")
_llms_lines += [
    "", "## Other pages", "",
    f"- [Reviews]({SITE_URL}/reviews/index.html): In-depth, independently researched reviews of the brands listed on {SITE_NAME}.",
    f"- [Blog]({SITE_URL}/blog/index.html): AI tool comparisons across every category, plus PageLens.ai vs other AEO tools.",
    f"- [Compare Tools]({SITE_URL}/compare.html): Interactive tool to compare up to 3 AI tools side by side.",
    f"- [About]({SITE_URL}/about.html): How {SITE_NAME} researches and selects tools.",
    f"- [Submit a Tool]({SITE_URL}/submit-tool.html): Get an AI tool listed on {SITE_NAME}.",
]
with open(os.path.join(ROOT, "llms.txt"), "w") as f:
    f.write("\n".join(_llms_lines))

print("Build complete.")
print("Categories:", len(CATEGORIES))
print("Tools:", len(ALL_TOOLS))
print("Tool pages:", len(os.listdir(TOOLS_DIR)))
